INSERT INTO public.recipes (
  title, slug, description, image_url, source_url, category, cuisine,
  servings, prep_time_minutes, cook_time_minutes, difficulty, instructions,
  calories_per_serving, protein_g_per_serving, fat_g_per_serving, carbs_g_per_serving, fiber_g_per_serving, sodium_mg_per_serving,
  total_calories, total_protein_g, total_fat_g, total_carbs_g, total_fiber_g, total_sodium_mg, is_verified
) VALUES
  ('tôm rang nước cốt dừa ngon bá cháy', 'cach-lam-tom-rang-nuoc-cot-dua-ngon-ba-chay', 'Tôm đất hay tôm chỉ, tôm rảo là loại tôm được ưa chuộng trong ẩm thực. Tôm đất có vị thịt ngon, chứa nhiều dưỡng chất tốt cho sức khỏe, được ví von là sản vật thiên nhiên ban tặng. Trong các bữa ăn hàng ngày, chúng ta có thể dễ dàng tìm và chế [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/02/maxresdefault-2-1.jpg', 'https://bepxua.vn/cach-lam-tom-rang-nuoc-cot-dua-ngon-ba-chay/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Tôm bỏ đầu, râu, chỉ lưng; cho tôm vào thố, thêm nước và 1 muỗng cafe muối vào khuấy đều rồi rửa tôm với nước muối sau đó rửa sạch lại bằng nước."},{"step_number":2,"title":"Bước 2","description":"Cho tôm vào tô, thêm ½ muỗng cafe muối, ½ muỗng cafe bột ngọt, tiêu xay, 1 muỗng canh dầu ăn trộn đều ướp 15 phút."},{"step_number":3,"title":"Bước 3","description":"Cho vào chén 2 muỗng canh đường, 2 muỗng canh nước mắm, 2 muỗng canh tương ớt, 100ml nước cốt dừa khuấy đều. Cho tỏi vào máy xay gia vị xay nhuyễn."},{"step_number":4,"title":"Bước 4","description":"Cho dầu ăn vào chảo đun nóng, dầu nóng cho tỏi xay vào phi thơm rồi cho tôm đã ướp vào xào cho tôm đổi màu sau đó cho chén gia vị đã pha vào chảo đảo đều với tôm, đậy nắp rim lửa nhỏ đến khi cạn nước khoảng 45-60 phút."},{"step_number":5,"title":"Bước 5","description":"Tiếp tục rang tôm với lửa nhỏ đến khi khô thì tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Cho tôm rang nước dừa ra dĩa, ăn cùng cơm, cháo… và thưởng thức."}]'::jsonb, 195.8, 20.8, 1.9, 24, 1.3, 6130.2, 783.3, 83, 7.5, 95.9, 5.2, 24520.8, true),
  ('tỏi ngâm giấm chua ngọt trắng giòn', 'cach-lam-toi-ngam-giam-chua-ngot-trang-gion', 'Tỏi là thực phẩm rất đỗi quen thuộc với chúng ta. Trong căn bếp của mọi nhà đều không thể thiếu loại gia vị này. Ngoài việc làm tăng thêm gia vị cho món ăn, tỏi còn sở hữu giá trị dinh dưỡng cao và còn được xem là một vị thuốc cho sức khỏe. [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/11/maxresdefault-5.jpg', 'https://bepxua.vn/cach-lam-toi-ngam-giam-chua-ngot-trang-gion/', 'mon_man', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Tỏi cắt cuốn đầu tỏi, cho vào thau nước ngâm 60’. Sau khi ngâm bóc vỏ, cho tỏi ra thau. Cho vào thau tỏi 2 muỗng canh đường, 500ml nước lọc vào khuấy tan đường rồi đậy kín thau tỏi, ngâm 5-6h."},{"step_number":2,"title":"Bước 2","description":"Cho vào nồi 250ml nước lọc, 250ml giấm, 125 gram đường khuấy tan, nấu sôi 3 phút rồi tắt bếp để thật nguội."},{"step_number":3,"title":"Bước 3","description":"Tỏi sau khi ngâm vớt ra. Bắc nồi nước khác lên bếp đun sôi rồi đợi cho nước bớt nóng (khoảng 80C thì cho tỏi vào trụng sơ sau đó vớt ra rửa sạch lại."},{"step_number":4,"title":"Bước 4","description":"Dàn tỏi ra mẹt phơi ráo nước. Sau khi tỏi ráo thì cho vào hũ đã rửa sạch trụng nước sôi, rót nước giấm đường vào ngập tỏi rồi đậy nắp ngâm. Để hũ tỏi ngâm 5-7 ngày."},{"step_number":5,"title":"Bước 5","description":"Sau khi ngâm đem tỏi ra dùng, múc tép nhỏ ăn trước, tép to để ngâm thêm khoảng 2 ngày sẽ ngon hơn. Bảo quản tỏi ngâm ở ngăn mát."}]'::jsonb, 311.3, 7.5, 0.5, 69.4, 1.9, 22.5, 1245.4, 30, 2, 277.4, 7.5, 90, true),
  ('sườn chiên sả ớt ngon hết ý', 'cach-lam-suon-chien-sa-ot-ngon-het-y', 'Sườn non là phần thịt rất được ưa chuộng bởi sở hữu độ mềm ngọt tiêu chuẩn của thịt, dễ chế biến theo nhiều kiểu để cho ra nhiều món ăn thơm ngon, đa dạng. Sườn non xương nhỏ, nhiều thịt, sụn mềm, được đánh giá là phần ngon nhất trong các phần sườn heo, [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/07/suon-chien-sa-ot.jpg', 'https://bepxua.vn/cach-lam-suon-chien-sa-ot-ngon-het-y/', 'mon_man', 'vietnamese', 4, 15, 25, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cho muối vào nồi nước đun sôi lăn tăn rồi cho sườn đã rửa sạch vào trụng 2-3 phút, vớt ra xả lại nước để ráo."},{"step_number":2,"title":"Bước 2","description":"Cho vào tô sườn 2 muỗng canh nước mắm, ½ muỗng cafe bột ngọt, ½ muỗng cafe muối, ½ muỗng cafe ngũ vị hương, 2 muỗng canh dầu ăn rồi trộn đều, ướp 15 phút. Tiếp theo cho 2 muỗng canh bột bắp vào sườn trộn đều."},{"step_number":3,"title":"Bước 3","description":"Sả xắt lát. Tỏi bỏ vỏ. Cho tỏi, sả, ớt vào máy xay gia vị xay nhuyễn."},{"step_number":4,"title":"Bước 4","description":"Cho dầu ăn xăm xắp vào chảo (độ ngập khoảng ⅔ miếng sườn) đun nóng, dầu nóng cho sườn vào chiên lửa lớn đến khi vừa vàng rồi hạ lửa vừa chiên đến khi thịt chín đều thì tắt bếp vớt sườn ra, chừa lại 3 muỗng canh dầu."},{"step_number":5,"title":"Bước 5","description":"Đun nóng lại chảo dầu rồi cho tỏi sả ớt xay vào phi thơm, nêm ⅓ muỗng canh hạt nêm, ⅓ muỗng canh đường đảo đều đến khi sả thơm thì cho sườn chiên vào đảo đều, tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Cho sườn chiên sả ớt ra dĩa, ăn kèm cơm nóng và thưởng thức."}]'::jsonb, 399.7, 32.4, 22.5, 16.9, 0.6, 8831.7, 1598.7, 129.7, 89.9, 67.5, 2.4, 35326.6, true),
  ('Cách mới làm gà hấp muối trộn gỏi bắp chuối hấp dẫn ngon mê ly', 'cach-moi-lam-ga-hap-muoi-tron-goi-bap-chuoi-hap-dan-ngon-me-ly', 'Gà hấp muối là một món gà thơm ngon với cách hấp không cần nước giúp giữ được trọn vẹn hương vị của thịt gà. Món này được nhiều người ưu ái chọn cho các bữa tiệc ngày lễ, ngày họp mặt vì sở hữu hương vị cuốn hút, không nhiều dầu mỡ gây ngấy, [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/02/ga-hap-muoi-tron-goi.jpg', 'https://bepxua.vn/cach-moi-lam-ga-hap-muoi-tron-goi-bap-chuoi-hap-dan-ngon-me-ly/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Gà chà chanh muối rửa sạch, để ráo. Cho vào chén 1 muỗng canh hạt nêm, ⅓ muỗng cafe nghệ bột, 1 muỗng canh dầu ăn trộn đều. Dùng hỗn hợp vừa trộn xoa đều gà."},{"step_number":2,"title":"Bước 2","description":"Lót giấy bạc vào đáy nồi hấp, dàn đều muối hột lên giấy bạc. Sả đập dập, cắt khúc cho vào dàn đều trên lớp muối rồi đặt gà lên, đậy nắp hấp 30-35 phút."},{"step_number":3,"title":"Bước 3","description":"Bắp chuối lột bỏ phần già, xắt mỏng. Cho muối, vắt chanh pha loãng vào thau nước rồi cho bắp chuối vừa xắt vào ngâm để không bị thâm đen, xắt đến đâu ngâm đến đó. Ngâm bắp chuối 15-30 phút rồi vớt ra rửa lại 2-3 lần nước, để ráo."},{"step_number":4,"title":"Bước 4","description":"Lấy 2 quả ớt bỏ hạt, xắt sợi, 1 quả xắt nhỏ. Rau răm, húng lủi xắt nhỏ."},{"step_number":5,"title":"Bước 5","description":"Cho 1 muỗng canh muối hột, 3-4 muỗng canh đường, ớt xắt nhỏ vào cối giã nhuyễn rồi cho tiếp 1 muỗng canh nước mắm vào khuấy đều. Lấy 2 quả chanh vắt nước cốt rồi cho 3-4 muỗng canh nước cốt chanh vào cối nước mắm pha, thích chua hơn thì cho hết rồi khuấy đều."},{"step_number":6,"title":"Bước 6","description":"Gà hấp xong đem ra xé vừa ăn. Cho bắp chuối vào tô, rưới từ từ nước mắm trộn lên bóp trộn đều sau đó cho lần lượt gà xé, ớt sừng, rau răm, húng lủi vào trộn tiếp đến khi vừa ý."},{"step_number":7,"title":"Bước 7","description":"Cho gà trộn gỏi ra dĩa, rắc thêm đậu phộng rang hoặc mè rang tùy thích ăn kèm bánh phồng chiên và thưởng thức."}]'::jsonb, 127.2, 2.2, 1.3, 26.6, 0.5, 3116.6, 508.6, 8.9, 5.2, 106.6, 2.1, 12466.4, true),
  ('sườn xào chua ngọt cực ngon ăn là ghiền', 'cach-lam-suon-xao-chua-ngot-cuc-ngon-an-la-ghien', 'Rất nhiều người ưa chuộng các món từ thịt sườn bởi hương vị thơm ngon, thịt sườn không béo ngậy như thịt mỡ cũng không quá khô như thịt nạc. Thịt sườn mềm ngọt, có thể được chế biến theo nhiều kiểu khác nhau tạo ra nhiều món đa dạng được lòng từ người lớn [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/02/suon-xao-chua-ngot.jpg', 'https://bepxua.vn/cach-lam-suon-xao-chua-ngot-cuc-ngon-an-la-ghien/', 'mon_xao', 'vietnamese', 4, 15, 20, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cho gừng, hành tím, ít muối vào nồi nước, đun nước sủi tăm rồi cho sườn vào trụng 5 phút. Vớt sườn ra rửa lại, để ráo."},{"step_number":2,"title":"Bước 2","description":"Cho hành tím và tỏi vào máy xay gia vị xay nhuyễn. Cho sườn ra tô, thêm 1 muỗng canh hành tỏi xay, 1 muỗng canh hạt nêm, tiêu xay vào trộn đều, ướp 15 phút."},{"step_number":3,"title":"Bước 3","description":"Cho vào chén 3 muỗng canh đường, 3 muỗng canh nước mắm, 3 muỗng canh tương xí muội, 1 muỗng canh tương ớt, 1 muỗng canh tương cà, 3 muỗng canh giấm ăn, tiêu xay, ½ muỗng cafe bột ngọt, 200ml nước lọc rồi khuấy tan."},{"step_number":4,"title":"Bước 4","description":"Cho 3 muỗng canh bột năng vào tô sườn đã ướp trộn đều. Cho dầu ăn vào chảo đun nóng, dầu sôi cho sườn vào chiên vừa vàng thì tắt bếp, gắp sườn ra."},{"step_number":5,"title":"Bước 5","description":"Cho hết phần hành tỏi xay còn lại vào chảo phi thơm rồi cho sườn chiên và sốt chua ngọt đã pha vào đảo đều, rim lửa vừa 3-5 phút. Lật đều sườn trong lúc rim để sườn ngấm đều sốt. Đậy nắp, hạ lửa nhỏ rim cho sườn mềm."},{"step_number":6,"title":"Bước 6","description":"Cho gốc hành, ngò rí, mè trắng rang vào chảo sườn rồi tắt bếp. Múc sườn xào chua ngọt ra dĩa, ăn kèm salad, cơm nóng và thưởng thức."}]'::jsonb, 417.9, 32, 22.5, 21.7, 0.4, 4467.8, 1671.8, 128.1, 90, 86.9, 1.4, 17871.2, true),
  ('Công Thức Sốt Trộn Hủ Tiếu Gà Đậm Đà – Trộn Là Ghiền, Làm Là Mê!', '-cong-thuc-sot-tron-hu-tieu-ga-dam-da-tron-la-ghien-lam-la-me', 'Công thức sốt trộn hủ tiếu gà đậm đà, sánh mịn, thơm mùi dầu mè – Bếp chỉ tận tình từng bước để mọi người trộn tô hủ tiếu ngon như ngoài hàng ngay tại nhà.', 'https://bepxua.vn/wp-content/uploads/2026/09/668880788_1245887904364515_625230941822446975_n.jpg', 'https://bepxua.vn/%f0%9f%8d%9c-cong-thuc-sot-tron-hu-tieu-ga-dam-da-tron-la-ghien-lam-la-me/', 'mon_man', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1: 🍲 Luộc gà và chuẩn bị nước súp","description":"Đầu tiên, Bếp cho gà, hành tây, hành tím, gốc ngò rí, đường phèn và muối hột vào nồi cùng 3 lít nước. Luộc gà khoảng 15–20 phút tính từ lúc nước sôi, nhớ lật gà trong lúc luộc để gà chín đều từ trong ra ngoài nha mọi người.\n\n\n\nGà chín thì vớt ra để nguội bớt rồi xé thành từng miếng vừa ăn.\n\n\n\nPhần nước súp còn lại, Bếp vớt bỏ hành và gốc ngò rí, cho thêm gốc hành lá vào, nêm nếm lại cho vừa miệng để dùng kèm khi ăn – húp một ngụm là thấy ấm bụng liền!"},{"step_number":2,"title":"Bước 2: 🥢 Làm sốt trộn hủ tiếu \"bất bại\"","description":"Đây là bước quan trọng nhất quyết định độ ngon của cả tô hủ tiếu, các bạn làm kỹ nha:\n\n\n\n\nBắc chảo, phi thơm hành tỏi xay với 3 muỗng canh dầu ăn.\n\n\n\nCho lần lượt dầu hào Kum Chun, nước tương, đường, nước mắm và 1 vá nước luộc gà vào chảo.\n\n\n\nNấu sôi khoảng 2–3 phút đến khi sốt sánh lại, dậy mùi thơm là được.\n\n\n\nTắt bếp, cho tiêu xay và dầu mè vào khuấy đều là hoàn thành phần sốt.\n\n\n\n\nNước sốt lúc này phải sánh nhẹ, có màu nâu cánh gián đẹp mắt, nếm thử thấy vị mặn ngọt hài hoà, thoang thoảng thơm dầu mè là đạt chuẩn rồi đó!"},{"step_number":3,"title":"Bước 3: 🍽️ Trình bày và thưởng thức","description":"🔥 Trụng hủ tiếu: Trụng hủ tiếu khô trong nước sôi khoảng 2 phút, sau đó trụng nhanh giá và hẹ, giũ ráo nước.\n\n\n\n🥄 Trộn hủ tiếu: Cho 1 muỗng canh sốt trộn vào phần hủ tiếu vừa trụng, trộn đều để sợi hủ tiếu thấm sốt.\n\n\n\n✨ Hoàn thiện tô hủ tiếu:\n\n\n\n\nXếp gà xé lên trên mặt\n\n\n\nRưới thêm 1 muỗng sốt trộn nữa\n\n\n\nThêm rau răm, ớt sừng, xà lách\n\n\n\nRắc hành phi, tóp mỡ, tiêu xay lên trên\n\n\n\n\nNước súp thì múc ra bát riêng, ai thích thì thêm hành ngò, tiêu, vắt thêm chút chanh cho dậy vị.\n\n\n\nVậy là mọi người đã có ngay tô hủ tiếu trộn gà xé đậm đà, thơm phức, đẹp mắt như ngoài quán rồi đó!"}]'::jsonb, 294.2, 5.9, 21.6, 19.1, 2.2, 2969.2, 1176.7, 23.6, 86.3, 76.6, 8.7, 11877, true),
  ('bò lúc lắc khoai tây nhanh gọn siêu ngon', 'cach-lam-bo-luc-lac-khoai-tay-nhanh-gon-sieu-ngon', 'Bò lúc lắc-món ăn lấy cảm hứng từ ẩm thực Pháp là một trong những món ăn từ thịt bò rất được yêu thích. Tên gọi "lúc lắc" có thuyết là hiểu theo cách gọi lái từ "xúc xắc" vì hình dáng của thịt bò giống như các viên xúc xắc nhưng cũng được cho [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/MRl2D75l_Gw-HD.jpg', 'https://bepxua.vn/cach-lam-bo-luc-lac-khoai-tay-nhanh-gon-sieu-ngon/', 'mon_man', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Thịt thăn bò rửa sạch, xắt miếng vuông. Cho vào tô thịt bò 1 muỗng canh nước tương, 1 muỗng canh dầu hào, 2 muỗng canh nước cam rồi trộn đều."},{"step_number":2,"title":"Bước 2","description":"Khoai tây gọt vỏ, rửa sạch, xắt miếng vuông. Cho 1 muỗng cafe muối vào tô nước khuấy đều rồi ngâm khoai tây khoảng 10 phút sau đó rửa sạch lại khoai tây, lau khô."},{"step_number":3,"title":"Bước 3","description":"Hành tây lột vỏ, xắt và tách thành từng lát. Hành lá xắt nhỏ. Tỏi cho vào máy xay gia vị xay nhuyễn."},{"step_number":4,"title":"Bước 4","description":"Cho vào chén 1 muỗng canh hắc xì dầu, 1 muỗng canh dầu hào, 1 muỗng canh tương ớt, 1 muỗng cafe đường, 1 muỗng cafe tiêu xay rồi khuấy đều làm sốt xào."},{"step_number":5,"title":"Bước 5","description":"Cho 200ml dầu ăn vào chảo đun nóng, dầu nóng cho khoai tây vào chiên lửa vừa đến khi vàng đều rồi vớt ra để ráo dầu."},{"step_number":6,"title":"Bước 6","description":"Cho thịt bò vào chảo dầu chiên lửa lớn một phút rồi vớt ra."},{"step_number":7,"title":"Bước 7","description":"Chắt dầu trong chảo, để lại 2 muỗng canh rồi cho tỏi xay vào phi thơm. Cho thịt bò, khoai tây, hành tây, sốt xào vào đảo đều với lửa lớn khoảng một phút. Cho tiếp hành lá vào đảo đều và tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Cho bò lúc lắc khoai tây ra dĩa và thưởng thức."}]'::jsonb, 314, 26, 3.3, 45.2, 2.6, 1373.7, 1255.9, 103.8, 13.3, 180.7, 10.4, 5494.9, true),
  ('súp nui gà xé đặc biệt thơm ngon dinh dưỡng', 'cach-nau-sup-nui-ga-xe-dac-biet-thom-ngon-dinh-duong', 'Thịt gà là một trong những loại thịt phổ biến và được ưa chuộng nhất. Với hương vị thơm ngon, kết cấu mềm ngọt và giá trị dinh dưỡng cao, thịt gà đã trở thành nguyên liệu không thể thiếu trong nhiều món ăn đa dạng, từ các món truyền thống đến các món hiện [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/youthumb_Ub3ODJscg3s_maxres.jpg', 'https://bepxua.vn/cach-nau-sup-nui-ga-xe-dac-biet-thom-ngon-dinh-duong/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Sơ chế gà: chà muối cho sạch da, làm sạch lòng gà, bóp sạch nhớt mũi họng gà, chà chanh khử mùi hôi rồi rửa sạch lại. Cắt gà làm đôi."},{"step_number":2,"title":"Bước 2","description":"Cho vào tô nước lọc, 1 muỗng canh bột mì khuấy đều. Nấm rơm gọt chỗ dơ, cho vào tô nước bột mì ngâm 10 phút rồi rửa sạch lại, chẻ đôi nấm to."},{"step_number":3,"title":"Bước 3","description":"Hành tây, hành tím lột vỏ. Cà rốt, củ sắn bào vỏ. Bắp bỏ vỏ. Hành ngò bỏ gốc. Cho rau củ vào thau ngâm nước muối  rồi rửa sạch lại. Cà rốt, củ sắn xắt miếng to. Bắp xắt khúc dày 2cm.Hành tím xắt lát. Giá hẹ rửa sạch."},{"step_number":4,"title":"Bước 4","description":"Cho vào nồi 3,5l nước lọc, 1 muỗng canh muối hạt, 1 muỗng canh đường phèn rồi cho hành tây, bắp, cà rốt, củ sắn vào nồi hầm 20 phút với lửa nhỏ cho ra nước ngọt."},{"step_number":5,"title":"Bước 5","description":"Thêm 1 chén nước lọc vào nồi rau củ rồi cho gà vào luộc 25-30 phút, lật gà trong lúc luộc cho gà chín đều."},{"step_number":6,"title":"Bước 6","description":"Cho dầu ăn vào chảo đun nóng, dầu nóng cho hành tím vào phi vừa vàng thì tắt bếp trút ra chén."},{"step_number":7,"title":"Bước 7","description":"Cho 2l nước lọc và 1 muỗng canh dầu ăn vào nồi khác đun nóng, dầu nóng cho ½ muỗng cafe muối và nui vào luộc nui khoảng 10-12 phút( gia giảm tùy theo loại nui). Nui mềm thì vớt nui ra xả lại nước lạnh, rưới 2 muỗng canh dầu hành phi vào trộn đều để nui bóng và không bị dính."},{"step_number":8,"title":"Bước 8","description":"Sau khi gà chín thì vớt gà ra để bớt nóng rồi xé thịt gà thành miếng vừa ăn. Vớt bỏ hành tây trong nồi rồi cho nấm rơm, 1 muỗng canh hạt nêm, 1 muỗng cafe muối hạt vào đảo đều nấu thêm 5 phút thì tắt bếp, cho gốc hành lá vào."},{"step_number":9,"title":"Bước 9","description":"Xếp thịt gà ra dĩa, thêm hành phi và ngò rí tùy thích. Cho giá, hẹ, nui, thịt gà vào tô rồi chan nước súp vào, thêm hành ngò, ớt, tiêu xay, hành phi, chanh… tùy ý và thưởng thức."}]'::jsonb, 151.5, 4.9, 3.4, 25.4, 1.7, 6323.9, 606.2, 19.4, 13.6, 101.5, 6.9, 25295.5, true),
  ('ốc nướng tiêu xanh siêu thơm ngon quên sầu', 'cach-lam-oc-nuong-tieu-xanh-sieu-thom-ngon-kho-quen', '“Đi ăn ốc đi” là câu nói quen miệng của những hội tín đồ ẩm thực khi tụ họp. Từ Nam ra Bắc, món ốc luôn rất được ưa chuộng. Món ăn đường phố nức tiếng này không bao giờ mất đi sức hút, rất dễ thấy trên các nẻo đường những hàng quán bán [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/07/maxresdefault-5-1.jpg', 'https://bepxua.vn/cach-lam-oc-nuong-tieu-xanh-sieu-thom-ngon-kho-quen/', 'mon_nuong', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cho vào thau ốc lác và vài cái muỗng, nĩa inox, 10 gram ớt xắt nhỏ rồi đổ nước ngập ngâm cho ốc nhả nhớt sau đó rửa sạch lại."},{"step_number":2,"title":"Bước 2","description":"Cho vào chảo sả cây đập dập rồi cho ốc, lá ổi vò sơ vào, đậy nắp đun sôi bùng. Chảo sôi mở nắp đảo đều cho ốc bung mài là được. Đem ốc ra giũ, lau sạch nước, nếu nướng than thì cắt đuôi ốc."},{"step_number":3,"title":"Bước 3","description":"Cho gốc hành lá, hành tím, gừng, 10 gram ớt vào máy xay gia vị xay nhuyễn. Tiêu xanh đem giã nát."},{"step_number":4,"title":"Bước 4","description":"Cho 2 muỗng canh dầu ăn vào chảo khác đun nóng, dầu nóng cho hành gừng ớt xay vào phi thơm rồi cho 2 muỗng canh nước mắm, 1 muỗng canh dầu hào,1 muỗng canh tương ớt, 1 muỗng cafe hạt nêm, ½ muỗng canh đường, 1 muỗng cafe tiêu xay, tiêu xanh đã giã sơ, 1 muỗng canh sốt ướp thịt nướng, 4 muỗng canh nước lọc khuấy đều nấu sôi và tắt bếp."},{"step_number":5,"title":"Bước 5","description":"Xếp ốc vào khay nướng, rưới sốt lên từng con ốc, xếp thêm lá chanh vào khay. Làm nóng nồi chiên không dầu 180 độ trong 5 phút rồi cho khay ốc vào nồi nướng 10 phút."},{"step_number":6,"title":"Bước 6","description":"Ốc nướng xong rắc thêm lá chanh xắt sợi nhỏ, kẹp rau răm tùy ý, chấm muối tiêu chanh và thưởng thức."}]'::jsonb, 262.7, 32.4, 3.6, 25.2, 8.3, 1441.8, 1050.8, 129.6, 14.3, 100.7, 33.1, 5767.1, true),
  ('cơm chiên trứng tỏi thơm mềm ngon miệng', 'cach-lam-com-chien-trung-toi-thom-mem-ngon-mieng', 'Cơm chiên là món ăn biến tấu với cơm quen thuộc rất được ưa thích. Với món cơm chiên, bạn có thể tiết kiệm được thời gian lẫn công sức thực hiện nhưng vẫn có ngay một món thơm ngon, dinh dưỡng. Tùy theo sở thích mà bạn dùng những nguyên liệu khác nhau chiên [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/06/maxresdefault-7.jpg', 'https://bepxua.vn/cach-lam-com-chien-trung-toi-thom-mem-ngon-mieng/', 'mon_an_sang', 'vietnamese', 4, 15, 25, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Tỏi cho vào máy xay gia vị xay nhuyễn. Đập 2 trứng vào tô cơm, thêm 1 muỗng cafe hạt nêm, 2 muỗng canh nước tương, ½ muỗng canh dầu điều, tiêu xay trộn đều. Hành lá xắt nhỏ."},{"step_number":2,"title":"Bước 2","description":"Cho 3 muỗng canh dầu ăn vào chảo và đun nóng, dầu nóng cho tỏi xay vào phi thơm đến khi tỏi vàng thì vớt ra. Đập 2 trứng vào chảo đánh tơi ra rồi cho cơm trộn vào đảo đều."},{"step_number":3,"title":"Bước 3","description":"Chiên cơm đến khi hạt cơm tơi và khô thì nêm 1 muỗng canh nước mắm, 1 muỗng cafe đường đảo đều rồi cho hành lá vào đảo tiếp. Sau đó cho tỏi phi vào trộn đều theo ý thích và tắt bếp."},{"step_number":4,"title":"Bước 4","description":"Cho cơm chiên ra dĩa, thêm tiêu xay tùy ý và thưởng thức."}]'::jsonb, 650.7, 21.7, 9.8, 118.8, 1.4, 1040.1, 2602.8, 86.7, 39.2, 475.4, 5.4, 4160.4, true),
  ('gà nấu nấm đông cô thập cẩm màu đẹp thơm nức ngon vô đối', 'cach-lam-ga-nau-nam-dong-co-thap-cam-mau-dep-thom-nuc-ngon-vo-doi', 'Thịt gà là nguyên liệu được nhiều người yêu thích lựa chọn cho các món ăn thơm ngon và giàu dinh dưỡng. Nằm trong nhóm thịt trắng được đánh giá là tốt cho sức khỏe hơn thịt đỏ, thịt gà là một loại thực phẩm không thể thiếu trong nhiều nền ẩm thực, trong đó [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/05/maxresdefault-1-4.jpg', 'https://bepxua.vn/cach-lam-ga-nau-nam-dong-co-thap-cam-mau-dep-thom-nuc-ngon-vo-doi/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Gà rửa sạch, chặt thành từng miếng vừa ăn. Nấm đông cô khô đem ngâm nước lạnh cho mềm."},{"step_number":2,"title":"Bước 2","description":"Cho vào tô 1 muỗng canh bột bắp và nước lọc khuấy đều. Nấm rơm gọt phần dơ, vừa gọt vừa cho vào tô ngâm nước bột bắp khoảng 15 phút cho sạch."},{"step_number":3,"title":"Bước 3","description":"Hành tây, hành tím lột vỏ. Cà rốt bào vỏ. Bắp non gọt bỏ bớt phần cùi. Ngò rí cạo phần gốc cho sạch đất cát. Sau khi sơ chế rửa sạch rau củ quả. Hành tím cho vào máy xay gia vị xay nhuyễn. Hành tây xắt lát."},{"step_number":4,"title":"Bước 4","description":"Cho vào tô gà, ½ muỗng canh muối, ½ muỗng canh hạt nêm, ⅓ muỗng canh bột ngọt, ½ muỗng canh đường, ½ muỗng canh ớt rim, 1 muỗng canh hành tím xay, ½ muỗng cafe tiêu xay trộn đều, ướp 15-30 phút."},{"step_number":5,"title":"Bước 5","description":"Nấm đông cô ngâm xong rửa lại nhiều lần nước, nấm rơm rửa sạch lại. Cà rốt xắt lát sóng dày khoảng 0,5cm (tỉa hoa nếu thích), nấm rơm chẻ đôi nấm to."},{"step_number":6,"title":"Bước 6","description":"Cho 3 muỗng canh dầu điều vào nồi đun nóng, dầu nóng cho 1 muỗng canh hành tím xay vào phi thơm rồi cho thịt gà vào đảo đều đến khi thịt săn. Cho tiếp nước dừa tươi và 1l nước lọc vào nồi, xắt gốc ngò rí cho vào rồi đậy nắp nồi nấu đến khi nước sôi. Nước sôi hạ lửa vừa tiếp tục nấu thêm 5 phút nữa, vớt bọt khi nước sôi."},{"step_number":7,"title":"Bước 7","description":"Cho 2 muỗng canh dầu ăn vào chảo đun nóng rồi cho phần hành tím xay còn lại vào phi thơm sau đó cho cà rốt vào chảo đảo đều. Tiếp đến cho nấm và bắp non, nêm ½ muỗng canh hạt nêm xào đều khoảng 1 phút."},{"step_number":8,"title":"Bước 8","description":"Vớt bỏ gốc ngò rí trong nồi thịt gà rồi cho củ vừa xào vào nấu thêm 10 phút, luôn vớt bọt trong lúc nấu. Nêm thêm 1 muỗng cafe hạt nêm, 1 muỗng cafe muối vào đảo đều, nấu thêm một chút rồi cho hành tây vào và tắt bếp."},{"step_number":9,"title":"Bước 9","description":"Múc gà nấu nấm đông cô ra tô, ăn với bún hoặc cơm nóng và thưởng thức."}]'::jsonb, 1300.3, 88.2, 87.5, 35.2, 5.4, 13615.6, 5201.4, 352.8, 350.1, 140.8, 21.5, 54462.2, true),
  ('Cá Chim Kho Thơm Đậm Đà, Cá Mềm Không Tanh', 'cach-lam-ca-chim-kho-thom-dam-da-ca-mem-khong-tanh-hao-com-cuc', 'Mấy chị em nội trợ ơi, hôm nay mình chia sẻ món cá chim kho thơm – món ăn quen thuộc của bữa cơm nhà mà lúc nào nấu lên cũng hết sạch nồi cơm luôn á. Vị chua nhẹ của thơm hòa cùng nước kho đậm đà, cá chim mềm béo thấm gia vị [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/Snapshot_20260902160033.jpg', 'https://bepxua.vn/cach-lam-ca-chim-kho-thom-dam-da-ca-mem-khong-tanh-hao-com-cuc/', 'mon_kho', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1: Sơ chế cá","description":"Cá chim mua về chà đều gừng giã nát, muối và chanh khắp mình cá, chà từ ngoài vào trong để khử sạch mùi tanh. Sau đó rửa lại với nước sạch, cắt khúc vừa ăn để ráo."},{"step_number":2,"title":"Bước 2: Chuẩn bị nguyên liệu","description":"Hành tím, tỏi, ớt đem xay nhuyễn. Thơm chia làm hai phần: một ít cắt lát, một ít băm nhỏ. Hành lá xắt khúc, ớt trái đập dập để riêng."},{"step_number":3,"title":"Bước 3: Chiên sơ cá","description":"Bắc chảo dầu nóng, cho gừng băm, hỗn hợp hành tỏi ớt xay và 1 muỗng cà phê muối vào phi thơm. Sau đó cho cá vào chiên sơ đến khi cá săn lại thì chắt bớt dầu ra, chỉ để lại khoảng 1 muỗng canh dầu trong chảo."},{"step_number":4,"title":"Bước 4: Xào sốt kho","description":"Cho thêm 1 muỗng canh hành, tỏi, ớt vào phi thơm lại lần nữa, tiếp đến cho thơm băm vào xào khoảng 1-2 phút cho dậy mùi. Nêm vào 1 muỗng canh đường, 3 muỗng canh nước mắm, 1 muỗng canh tương ớt và 1 muỗng canh tương cà, đảo đều cho hòa quyện."},{"step_number":5,"title":"Bước 5: Kho cá","description":"Cho cá đã chiên vào chảo sốt, lật đều hai mặt cho cá thấm gia vị. Đổ vào 400ml nước nóng cùng 1 muỗng cà phê nước màu dừa, kho với lửa vừa khoảng 10 phút cho cá thấm đều và nước kho sánh lại."},{"step_number":6,"title":"Bước 6: Hoàn thành","description":"Cho phần thơm cắt lát vào, kho thêm 5 phút cho thơm chín mềm mà vẫn giữ được độ giòn nhẹ. Cuối cùng rắc hành lá và ớt lên trên là xong."}]'::jsonb, 101.9, 2.2, 0.6, 22.1, 1.3, 3134.2, 407.6, 8.9, 2.2, 88.5, 5, 12536.7, true),
  ('Gà Rang Muối Giòn Rụm Thơm Lừng', 'ga-rang-muoi-gion-rum-thom-lung-cong-thuc-don-gian-ai-cung-lam-duoc', 'Nhà mình hay đổi món cuối tuần, mà món gà rang muối này là "cứu tinh" mỗi khi cả nhà thèm ăn vặt mà lười ra ngoài. Da gà giòn rụm, thịt bên trong mềm mọng không hề bị khô, lại thơm nức mùi sả với lá chanh. Làm một lần là ghiền, con nít [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/08/ga-rang-muoi-web.jpg', 'https://bepxua.vn/ga-rang-muoi-gion-rum-thom-lung-cong-thuc-don-gian-ai-cung-lam-duoc/', 'mon_man', 'vietnamese', 3, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1: Ướp gà","description":"Gà cắt miếng vừa ăn cho vào tô, thêm 1 muỗng canh nước mắm, trộn đều rồi ướp khoảng 15-20 phút cho gà thấm gia vị. Sau đó cho thêm 1 muỗng canh bột chiên giòn vào, trộn đều lần nữa. Bột chiên giòn này là bí quyết giúp lớp da gà sau khi chiên giòn tan mà không bị cứng đâu nha."},{"step_number":2,"title":"Bước 2: Chiên sả và lá chanh","description":"Bắc chảo dầu lên bếp, đun nóng dầu rồi cho sả và lá chanh vào chiên lửa vừa cho đến khi vàng giòn và dậy mùi thơm. Bước này đơn giản nhưng quan trọng lắm, vì sả lá chanh chiên giòn chính là \"linh hồn\" tạo mùi thơm đặc trưng cho món ăn."},{"step_number":3,"title":"Bước 3: Chiên gà","description":"Cho thịt gà đã ướp vào chảo dầu, chiên với lửa vừa. Khi thấy gà vừa lên màu vàng thì tăng lửa lớn để gà giòn hơn và bớt ngấm dầu. Chiên đến khi miếng gà vàng ươm, thơm ngất ngây thì vớt ra để ráo dầu."},{"step_number":4,"title":"Bước 4: Trộn gia vị rang muối","description":"Cho gà vừa chiên ra tô, thêm phần sả chiên đã làm ở bước 2, rắc 2 muỗng canh bột rang muối và một ít lá chanh xắt sợi vào, đảo đều tay cho gia vị bám đều lên từng miếng gà."}]'::jsonb, 1162.7, 3.1, 1, 285.4, 5.4, 3883.7, 3488, 9.3, 3, 856.1, 16.3, 11651.2, true),
  ('mắm kho chuẩn vị đậm chất đồng quê', 'cach-nau-mam-kho-chuan-vi-dam-chat-dong-que', '“Muốn ăn bông súng mắm kho, thì về Đồng Tháp ăn cho đỡ thèm.” Không chỉ Đồng Tháp, mà trên khắp xứ mắm miền Tây sông nước, các món mắm từ đâu đã nổi danh là đặc sản nơi đây. Hương vị của mắm đã trở thành một nét đặc trưng không thể thiếu trong [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/10/a74BAoOOSRY-HD.jpg', 'https://bepxua.vn/cach-nau-mam-kho-chuan-vi-dam-chat-dong-que/', 'mon_kho', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cho mắm cá linh, mắm cá sặc, nước dừa tươi vào nồi nấu sôi, vớt bọt. Nấu đến khi mắm nhừ."},{"step_number":2,"title":"Bước 2","description":"Cà tím xắt khúc, chẻ vừa ăn. Đậu bún xắt khúc, bỏ cọng sâu. Đậu bắp lặt bỏ râu. Cho tất cả vào ngâm nước muối 10 phút rồi rửa sạch vớt ra. Đậu bắp bỏ đầu xắt khúc. Rau ăn kèm lặt lá hư, rửa sạch."},{"step_number":3,"title":"Bước 3","description":"Cá bông lau làm rửa sạch, xắt khúc dày 2cm. Thịt ba chỉ bóp muối rửa sạch, xắt miếng vừa ăn."},{"step_number":4,"title":"Bước 4","description":"Tỏi, sả bào, hành tím, ớt sừng cho vào máy xay gia vị xay nhuyễn. Cho vào thau thịt, cá, ½ phần hành tỏi sả ớt xay, 1 muỗng canh hạt nêm, ⅓ muỗng canh bột ngọt trộn đều."},{"step_number":5,"title":"Bước 5","description":"Cho 2 muỗng canh dầu ăn vào nồi khác đun nóng, dầu nóng cho phần hành tỏi sả ớt xay còn lại vào phi thơm rồi cho thịt đã ướp vào xào săn. Tiếp theo cho cá vào, lật cá xào săn đều 2 mặt."},{"step_number":6,"title":"Bước 6","description":"Rây mắm cho vào nồi, nêm 1 muỗng canh nước màu đường nấu lửa vừa khoảng 15 phút."},{"step_number":7,"title":"Bước 7","description":"Vớt cá ra, cho cà tím, đậu bắp vào nồi nấu lửa vừa khoảng 2 phút thì cho đậu bún, 1 muỗng canh đường, ⅓ muỗng canh bột ngọt (gia giảm theo khẩu vị) vào đảo đều."},{"step_number":8,"title":"Bước 8","description":"Cho lại cá vào nồi, thêm ớt sừng xắt nhỏ nấu sôi lại rồi tắt bếp. Múc mắm kho ra tô, ăn với rau xanh và thưởng thức."}]'::jsonb, 498.7, 25.4, 27.2, 33.9, 3.4, 4544.2, 1994.9, 101.6, 108.7, 135.5, 13.4, 18176.8, true),
  ('canh chua cá diêu hồng ngọt thanh đậm đà', 'cach-nau-canh-chua-ca-dieu-hong-ngot-thanh-dam-da', 'Cá diêu hồng là một loại cá nước ngọt phổ biến ở Việt Nam, thường được nuôi trong ao hồ hoặc sông suối. Loài cá này có nguồn gốc từ cá rô phi và được lai tạo để có màu hồng cam đẹp mắt. Cá diêu hồng là một lựa chọn tuyệt vời cho những [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/10/bhP9n1ee9I-HD.jpg', 'https://bepxua.vn/cach-nau-canh-chua-ca-dieu-hong-ngot-thanh-dam-da/', 'mon_canh', 'vietnamese', 4, 15, 20, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cá diêu hồng chà chanh muối cho sạch nhớt, khử mùi tanh rồi rửa sạch, xắt khúc vừa ăn, rửa lại cho sạch."},{"step_number":2,"title":"Bước 2","description":"Bạc hà tuốt vỏ, rửa sạch cùng rau củ khác. Bạc hà, thơm xắt lát. Cà chua xắt múi. Đậu bắp xắt khúc xéo. Rau nêm xắt nhỏ. Ớt sừng xắt lát. Tỏi cho vào máy xay gia vị xay nhuyễn."},{"step_number":3,"title":"Bước 3","description":"Cho 2 muỗng canh dầu ăn vào chảo đun nóng, dầu nóng cho tỏi xay vào phi vừa vàng rồi cho ra chén, chừa lại ít trong chảo."},{"step_number":4,"title":"Bước 4","description":"Cho vào chảo thơm, cà chua, 2 muỗng cafe đường, 1 muỗng cafe hạt nêm xào sơ 1-2 phút rồi cho ra tô."},{"step_number":5,"title":"Bước 5","description":"Cho cá vào chảo chiên sơ, gắp ra dĩa."},{"step_number":6,"title":"Bước 6","description":"Nấu sôi sủi tăm 1,7l nước rồi cho cá vào, nêm 1 muỗng cafe vung muối,  2 muỗng canh đường nấu sôi sau đó cho me chín vào gạn lấy nước chua; nấu tiếp cho cá chín khoảng 10 phút."},{"step_number":7,"title":"Bước 7","description":"Vớt cá ra, cho thơm, cà chua, đậu bắp vào nấu lửa vừa khoảng 1 phút rồi cho bạc hà, giá đỗ, 1 muỗng canh nước mắm vào đảo đều."},{"step_number":8,"title":"Bước 8","description":"Cho cá lại vào nồi, cho tiếp rau nêm, ớt, tỏi phi (nếu ăn liền) vào và tắt bếp."},{"step_number":9,"title":"Bước 9","description":"Múc canh chua cá diêu hồng ra tô, ăn với cơm nóng và thưởng thức."}]'::jsonb, 251.5, 11.5, 1.9, 46.7, 0.9, 1150.9, 1006, 46.2, 7.7, 187, 3.7, 4603.7, true)
